 "content": "def transform(grid):
    """Repair isolated-color speckles in otherwise solid rectangular regions."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # A real object/background color forms at least one solid 2x2 patch;
    # colors lacking such a patch are the scattered corruption colors.
    has_patch = {v: False for v in counts}
    for r in range(h - 1):
        for c in range(w - 1):
            v = grid[r][c]
            if grid[r][c+1] == v and grid[r+1][c] == v and grid[r+1][c+1] == v:
                has_patch[v] = True
    noise = {v for v in counts if not has_patch[v] and v != background}

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in noise:
                continue
            nearby = {}
            for rr in range(max(0, r-1), min(h, r+2)):
                for cc in range(max(0, c-1), min(w, c+2)):
                    v = grid[rr][cc]
                    if (rr, cc) != (r, c) and v not in noise:
                        nearby[v] = nearby.get(v, 0) + 1
            # Correct a speck to an object color only when the local evidence
            # is strong; otherwise it was on the background.
            candidates = [(n, v) for v, n in nearby.items() if v != background and n >= 3]
            out[r][c] = max(candidates)[1] if candidates else background
    return out
